const fs = require('fs');
const path = require('path');

const dir = __dirname;
const input = fs.readFileSync(path.join(dir, 'README.md'), 'utf8');
const headings = input
  .split(/\r?\n/)
  .filter((line) => line.startsWith('#'));

fs.writeFileSync(path.join(dir, 'INDEX.md'), headings.join('\n') + '\n');

